import io
import sqlite3
from sync.client import VendorClient, http_get_json

requests = []
def fetch(url):
    requests.append(url)
    return http_get_json(url)

records = list(VendorClient(fetch_json=fetch, notices=io.StringIO()).iter_items())
old = sqlite3.connect('/tmp/catalog-before-cat218.db')
new = sqlite3.connect('data/catalog.db')
before = {r[0]: r for r in old.execute('SELECT * FROM products')}
after = {r[0]: r for r in new.execute('SELECT * FROM products')}
expected = dict(before)
for item in records:
    sku = item['sku']
    if sku in expected and expected[sku][3] == 'manual':
        continue
    if item.get('deleted'):
        expected.pop(sku, None)
    else:
        expected[sku] = (sku, item['name'], item['price_paise'], 'vendor', item['updated_at'])
assert after == expected, 'Database differs from expected full feed merge'
manual_before = {k: v for k, v in before.items() if v[3] == 'manual'}
assert {k: v for k, v in after.items() if v[3] == 'manual'} == manual_before
mentioned = {item['sku'] for item in records}
assert all(after[k] == v for k, v in before.items() if k not in mentioned)
print(f'Validated {len(records)} feed records across {len(requests)} cursor pages.')
print(f'Database exactly matches expected merge: {len(after)} rows; all {len(manual_before)} manual rows unchanged.')
print('Sync state:', new.execute('SELECT * FROM sync_state').fetchall())
old.close()
new.close()
